INSERT INTO `blogs` (`id`, `blog_category_id`, `title`, `title_ar`, `slug`, `description`, `description_ar`, `view`, `image`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'Top Real Estate Market Trends in 2025', 'أحدث اتجاهات سوق العقارات في 2025', 'top-real-estate-market-trends-in-2025', 'An in-depth look at shifts in the real estate market this year, including property prices, high-demand areas, and the impact of economic developments on real estate investment.', '<font color=\"#424242\" face=\"Inter, sans-serif\"><span style=\"letter-spacing: normal;\">نظرة معمقة على التحولات في سوق العقارات خلال هذا العام، بما في ذلك أسعار العقارات، المناطق الأكثر رواجًا، وتأثير التطورات الاقتصادية على الاستثمار العقاري.</span></font>', 553, '66c2e2c2e032e1724048066.png', 'active', '2024-04-05 22:32:38', '2026-02-22 06:19:47'),
(2, 1, 'Key Tips Before Buying a Property', 'نصائح مهمة قبل شراء عقار', 'key-tips-before-buying-a-property', 'Steps to take before making a purchase decision, from checking legal documents to evaluating the property, and the importance of hiring a professional real estate advisor.', '<div style=\"background-color: rgb(245, 251, 255);\"><font color=\"#000000\" face=\"Inter, sans-serif\"><span style=\"letter-spacing: normal;\">خطوات يجب اتباعها قبل اتخاذ قرار الشراء، من فحص الأوراق القانونية إلى تقييم العقار، وأهمية الاستعانة بمستشار عقاري محترف.</span></font></div>', 458, '66c2e2ce23be91724048078.png', 'active', '2024-05-22 10:36:18', '2026-02-22 06:19:55'),
(3, 1, 'How to Choose the Right Investment Property', 'كيفية اختيار العقار المناسب للاستثمار', 'how-to-choose-the-right-investment-property', 'Criteria for selecting the best investment property, such as location, property type, expected returns, and future growth potential.', '<font color=\"#424242\" face=\"Inter, sans-serif\"><span style=\"letter-spacing: normal;\">معايير اختيار العقار الاستثماري الأفضل، مثل الموقع، نوع العقار، العائد المتوقع، وفرص النمو المستقبلية.</span></font>', 552, '66c2e2d7b04b51724048087.png', 'active', '2024-04-05 22:32:38', '2026-02-22 06:19:54'),
(4, 1, 'Rental Guide: Landlord and Tenant Rights and Responsibilities', 'دليل تأجير العقارات: حقوق وواجبات المالك والمستأجر', 'rental-guide-landlord-and-tenant-rights-and-responsibilities', 'A simplified explanation of the main laws governing rental agreements, and how both parties can protect their rights and ensure a successful rental experience.', '<div style=\"background-color: rgb(245, 251, 255);\"><font color=\"#000000\" face=\"Inter, sans-serif\"><span style=\"letter-spacing: normal;\">شرح مبسط للقوانين الأساسية التي تحكم عمليات التأجير، وكيفية حماية حقوق الطرفين وضمان تجربة إيجارية ناجحة.</span></font></div>', 474, '66c2e2eaf0cfd1724048106.png', 'active', '2024-05-22 10:36:18', '2026-02-22 06:19:53'),
(5, 1, 'Technology’s Impact on the Real Estate Market', 'التكنولوجيا وتأثيرها على سوق العقارات', 'technologys-impact-on-the-real-estate-market', 'How buying and selling properties has changed through tech tools like virtual reality, online platforms, and AI-powered property evaluations.', '<div><br></div><div>كيف تغيرت تجربة شراء وبيع العقارات بفضل التكنولوجيا، مثل استخدام الواقع الافتراضي، المنصات الإلكترونية، والذكاء الاصطناعي في تقييم العقارات.</div>', 136, '6832d2314f9541748161073.jpeg', 'active', '2025-05-25 11:15:03', '2026-02-09 06:39:45'),
(6, 1, 'Best Cities in Saudi Arabia for Real Estate Investment in 2025', 'أفضل المدن السعودية للاستثمار العقاري في 2025', 'best-cities-in-saudi-arabia-for-real-estate-investment-in-2025', 'A spotlight on the most attractive Saudi cities and areas for real estate investors, with analysis of opportunities and challenges.', 'تسليط الضوء على المدن والمناطق الأكثر جذبًا للمستثمرين العقاريين داخل المملكة، مع تحليل الفرص والتحديات.', 149, '6832c91ae552c1748158746.jpg', 'active', '2025-05-25 11:39:07', '2026-02-09 06:39:46'),
(7, 1, 'How to Finance Your Property the Smart Way', 'كيفية تمويل عقارك بأفضل الطرق', 'how-to-finance-your-property-the-smart-way', 'An overview of available real estate financing options, including bank loans, Islamic finance, government support programs, and tips to improve your chances of getting approved.', 'شرح خيارات التمويل العقاري المتاحة، مثل القروض البنكية، التمويل الإسلامي، برامج الدعم الحكومي، ونصائح لرفع فرص الحصول على تمويل مناسب.', 122, '6832c9c5057071748158917.jpg', 'active', '2025-05-25 11:41:57', '2026-02-09 06:39:45'),
(8, 1, 'Property Types Explained: Residential, Commercial, Industrial', 'الفرق بين أنواع العقارات: سكني، تجاري، صناعي', 'property-types-explained-residential-commercial-industrial', 'An outline of each property type’s features, and how to choose the right one based on your investment goals or usage needs.', 'توضيح خصائص كل نوع من العقارات، وكيفية اختيار النوع المناسب حسب الهدف من الاستثمار أو الاستخدام.', 112, '6832caab9f6e11748159147.jpg', 'active', '2025-05-25 11:45:47', '2026-02-09 06:39:46');
