INSERT INTO `events` (`id`, `title`, `title_ar`, `slug`, `category_id`, `country_id`, `city_id`, `type`, `audience_type`, `sector`, `start_time`, `end_time`, `same_time`, `address`, `latitude`, `longitude`, `image`, `description`, `description_ar`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Kingdom of Saudi Property show Luxury Events.', 'المملكة العربية السعودية معرض العقارات الأحداث الفاخرة.', 'kingdom-of-saudi-property-show-luxury-events', 1, 198, 1, 'Exhibition', 'General', 'Exhibition', '2024-05-09 19:23:00', '2024-05-16 19:23:00', '0', '7531 Saud Abdullah Ash Shammari, Ghirnatah', '24.789694443997565', '46.73257785180664', '66c2d6e3a35921724045027.png', '<span data-metadata=\"<!--(figmeta)eyJmaWxlS2V5IjoiR2pFVlkyQjVyR0VqRlNpQmRkQVJ4dyIsInBhc3RlSUQiOjEzODY2Nzc4NDAsImRhdGFUeXBlIjoic2NlbmUifQo=(/figmeta)-->\"></span><span data-buffer=\"<!--(figma)(/figma)-->\"></span><span style=\"white-space-collapse: preserve;\">The Minister of Municipal, Rural Affairs and Housing, Chairman of the Board of Directors of the Real Estate Authority, Majid bin Abdullah Al-Hogail, inaugurates the second edition of the Second Maskan Real Estate Exhibition 2024. It is sponsored by the Ministry of Municipal, Rural Affairs and Housing and the General Real Estate Authority, and with the participation of a number of government agencies, banks, finance and real estate development companies.<br>The exhibition aims to provide a complete journey for the beneficiary to own his home by facilitating communication with developers and financing agencies and providing them with the necessary consultations. It also includes holding workshops and launching real estate investment funds. It also presented the most important real estate projects for developers, financing</span><span data-metadata=\"<!--(figmeta)eyJmaWxlS2V5IjoiR2pFVlkyQjVyR0VqRlNpQmRkQVJ4dyIsInBhc3RlSUQiOjMzMjI1Nzk4MiwiZGF0YVR5cGUiOiJzY2VuZSJ9Cg==(/figmeta)-->\"></span><span data-buffer=\"<!--(figma)(/figma)-->\"></span><span style=\"white-space-collapse: preserve;\">The Minister of Municipal, Rural Affairs and Housing, Chairman of the Board of Directors of the Real Estate Authority, Majid bin Abdullah Al-Hogail, inaugurates the second edition of the Second Maskan Real Estate Exhibition 2024. It is sponsored by the Ministry of Municipal, Rural Affairs and Housing and the General Real Estate Authority, and with the participation of a number of government agencies, banks, finance and real estate development companies.<br>The exhibition aims to provide a complete journey for the beneficiary to own his home by facilitating communication with developers and financing agencies and providing them with the necessary consultations. It also includes holding workshops and launching real estate investment funds. It also presented the most important real estate projects for developers, financing&nbsp;</span><br>', '<div>افتتح وزير الشؤون البلدية والقروية والإسكان رئيس مجلس إدارة المؤسسة العقارية ماجد بن عبدالله الحقيل النسخة الثانية من معرض مسكن العقاري الثاني 2024 برعاية وزارة البلدية وشئون الريف والإسكان والهيئة العامة العقارية، وبمشاركة عدد من الجهات الحكومية والبنوك وشركات التمويل والتطوير العقاري.</div><div>ويهدف المعرض إلى تقديم رحلة كاملة للمستفيد لامتلاك منزله من خلال تسهيل التواصل مع المطورين وجهات التمويل وتقديم الاستشارات اللازمة لهم. كما يتضمن عقد ورش عمل وإطلاق صناديق الاستثمار العقاري. كما عرضت أهم المشاريع العقارية للمطورين والتمويل وزير الشؤون البلدية والقروية والإسكان رئيس مجلس إدارة المؤسسة العقارية ماجد بن عبدالله الحقيل يفتتح النسخة الثانية من معرض مسكن العقاري الثاني المعرض العقاري 2024. يقام برعاية وزارة الشؤون البلدية والقروية والإسكان والهيئة العامة العقارية، وبمشاركة عدد من الجهات الحكومية والبنوك وشركات التمويل والتطوير العقاري.</div><div>ويهدف المعرض إلى تقديم رحلة كاملة للمستفيد لامتلاك منزله من خلال تسهيل التواصل مع المطورين وجهات التمويل وتقديم الاستشارات اللازمة لهم. كما يتضمن عقد ورش عمل وإطلاق صناديق الاستثمار العقاري. كما عرضت أهم المشاريع العقارية للمطورين والتمويل</div>', 1, '2024-05-09 11:23:31', '2024-08-19 09:23:47');
