(115, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Real estate finance\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a\",\"short_description\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">Contribute to granting real estate financing loans through partnership with many real estate finance companies in the Kingdom<\\/span><br \\/>\",\"short_description_ar\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">\\u0627\\u0644\\u0645\\u0633\\u0627\\u0647\\u0645\\u0629 \\u0641\\u064a \\u0645\\u0646\\u062d \\u0642\\u0631\\u0648\\u0636 \\u062a\\u0645\\u0648\\u064a\\u0644 \\u0639\\u0642\\u0627\\u0631\\u064a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0634\\u0631\\u0627\\u0643\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u062f\\u064a\\u062f \\u0645\\u0646 \\u0634\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a \\u0628\\u0627\\u0644\\u0645\\u0645\\u0644\\u0643\\u0629<\\/span><br \\/>\",\"button_url\":\"service-request\",\"image\":\"661f730cd3f821713337100.png\"}', 'basic', '2024-02-04 05:13:01', '2024-04-17 05:26:17'),
(116, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Evaluation\",\"title_ar\":\"\\u062a\\u0642\\u064a\\u064a\\u0645\",\"short_description\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">We have experts and offices specialized in evaluation to accurately determine the price of property in all its forms, whether it is land, residences, shops, farms, or factories.<\\/span><br \\/>\",\"short_description_ar\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">\\u0644\\u062f\\u064a\\u0646\\u0627 \\u062e\\u0628\\u0631\\u0627\\u0621 \\u0648\\u0645\\u0643\\u0627\\u062a\\u0628 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0644\\u062a\\u062d\\u062f\\u064a\\u062f \\u062b\\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0644\\u0627\\u0643 \\u0628\\u062f\\u0642\\u0629 \\u0628\\u0643\\u0627\\u0641\\u0629 \\u0627\\u0634\\u0643\\u0627\\u0644\\u0647\\u0627 \\u0633\\u0648\\u0627\\u0621 \\u0623\\u0643\\u0627\\u0646\\u062a \\u0623\\u0631\\u0627\\u0636\\u064a\\u060c \\u0623\\u0645 \\u0645\\u0633\\u0627\\u0643\\u0646\\u060c \\u0623\\u0645 \\u0645\\u062a\\u0627\\u062c\\u0631\\u060c \\u0623\\u0645 \\u0645\\u0632\\u0627\\u0631\\u0639\\u060c \\u0623\\u0645 \\u0645\\u0635\\u0627\\u0646\\u0639<\\/span><br \\/>\",\"button_url\":\"service-request\",\"image\":\"661f72d5835ff1713337045.png\"}', 'basic', '2024-02-04 05:13:20', '2024-04-17 05:25:16'),
(117, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Studies\",\"title_ar\":\"\\u062f\\u0631\\u0627\\u0633\\u0627\\u062a\",\"short_description\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">Property market is huge and has many needs, so an extensive market study is required before launching any project to know the needs and priorities of the segment that your company is addressing with this product.<\\/span><br \\/>\",\"short_description_ar\":\"<span style=\\\"color:rgb(108,117,125);font-family:Inter, sans-serif;letter-spacing:normal;\\\">\\u0633\\u0648\\u0642 \\u0627\\u0644\\u0623\\u0645\\u0644\\u0627\\u0643 \\u0636\\u062e\\u0645 \\u0648\\u0645\\u062a\\u0639\\u062f\\u062f \\u0627\\u0644\\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a, \\u0644\\u0630\\u0627 \\u064a\\u0644\\u0632\\u0645 \\u0639\\u0645\\u0644 \\u062f\\u0631\\u0627\\u0633\\u0629 \\u0633\\u0648\\u0642\\u064a\\u0629 \\u0645\\u0648\\u0633\\u0639\\u0629 \\u0642\\u0628\\u0644 \\u0625\\u0637\\u0644\\u0627\\u0642 \\u0623\\u064a \\u0645\\u0634\\u0631\\u0648\\u0639 \\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0648\\u0623\\u0648\\u0644\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u064a\\u062d\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062e\\u0627\\u0637\\u0628\\u0647\\u0627 \\u0634\\u0631\\u0643\\u062a\\u0643 \\u0628\\u0647\\u0630\\u0627 \\u0627\\u0644\\u0645\\u0646\\u062a\\u062c<\\/span><br \\/>\",\"button_url\":\"service-request\",\"image\":\"661f731ed1f1c1713337118.png\"}', 'basic', '2024-02-04 05:13:41', '2024-04-17 05:24:37'),
