(199, 'submission_criteria.element', '{\"title\":\"Invite candidates whose needs and motivations align with our mission for a one-on-one interview in our offices\",\"title_ar\":\"\\u0642\\u0645 \\u0628\\u062f\\u0639\\u0648\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0634\\u062d\\u064a\\u0646 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u062a\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a\\u0647\\u0645 \\u0648\\u062f\\u0648\\u0627\\u0641\\u0639\\u0647\\u0645 \\u0645\\u0639 \\u0645\\u0647\\u0645\\u062a\\u0646\\u0627 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u0642\\u0627\\u0628\\u0644\\u0629 \\u0641\\u0631\\u062f\\u064a\\u0629 \\u0641\\u064a \\u0645\\u0643\\u0627\\u062a\\u0628\\u0646\\u0627\"}', NULL, '2024-03-17 13:35:51', '2024-03-17 13:35:51'),
(200, 'submission_criteria.element', '{\"title\":\"Responding to applicants and communicating with them to study the cases of applicants through the Hemam Call Center platform\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0644\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u064a\\u0646 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0647\\u0645 \\u0644\\u062f\\u0631\\u0627\\u0633\\u0629 \\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u064a\\u0646 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0645\\u0646\\u0635\\u0629 \\u0645\\u0631\\u0643\\u0632 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0647\\u0645\\u0627\\u0645\"}', NULL, '2024-03-17 13:36:05', '2024-03-17 13:36:05'),
(201, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Reconciling relations\",\"title_ar\":\"\\u0625\\u0635\\u0644\\u0627\\u062d \\u0630\\u0627\\u062a \\u0627\\u0644\\u0628\\u064a\\u0646\",\"short_description\":\"<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:14pt;line-height:107%;\\\">We fully believe Amlaek in the importance of eliminating the\\ncauses of disputes and conflict, through tolerance and forgiveness, or by\\nmutual consent. This is represented in the importance of reconciling relations\\nbetween a single family, partners and family companies.<\\/span><\\/p><p><\\/p>\",\"short_description_ar\":\"<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\"><span lang=\\\"ar-eg\\\" style=\\\"font-size:18pt;line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-eg\\\">\\u0646\\u062d\\u0646 <\\/span><span lang=\\\"ar-eg\\\" style=\\\"font-size:18pt;line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-eg\\\">\\u0646\\u0648\\u0645\\u0646 \\u0627\\u064a\\u0645\\u0627\\u0646\\n\\u062a\\u0627\\u0645 \\u0641\\u064a \\u062a\\u0646\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0627\\u0645\\u0644\\u0627\\u0643 \\u0628\\u0623\\u0647\\u0645\\u064a\\u0629 <\\/span><span lang=\\\"ar-sa\\\" style=\\\"font-size:18pt;line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-sa\\\">\\u0625\\u0632\\u0627\\u0644\\u0629 \\u0623\\u0633\\u0628\\u0627\\u0628 \\u0627\\u0644\\u062e\\u0635\\u0627\\u0645 \\u0648\\u0627\\u0644\\u0646\\u0632\\u0627\\u0639\\u060c \\u0628\\u0627\\u0644\\u062a\\u0651\\u0633\\u0627\\u0645\\u062d \\u0648\\u0627\\u0644\\u0639\\u0641\\u0648\\u060c \\u0623\\u0648 \\u0628\\u0627\\u0644\\u062a\\u0651\\u0631\\u0627\\u0636\\u064a, <\\/span><span lang=\\\"ar-eg\\\" style=\\\"font-size:18pt;line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-eg\\\">\\u0648\\u064a\\u062a\\u0645\\u062b\\u0644 \\u0630\\u0644\\u0643\\n\\u0628\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0628\\u064a\\u0646 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0627\\u0633\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0627\\u062d\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0634\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u064a\\u0629<\\/span><span dir=\\\"ltr\\\" style=\\\"font-size:18pt;line-height:107%;\\\"><\\/span><\\/p><p><\\/p>\",\"button_url\":\"service-request\",\"image\":\"661f72b217f4c1713337010.png\"}', NULL, '2024-03-18 15:51:52', '2024-04-28 15:41:05'),
(202, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Taqbeel of projects\",\"title_ar\":\"\\u062a\\u0642\\u0628\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639\",\"short_description\":\"<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">Offers to accept projects with their assets and liabilities\\naccording to the agreement between the parties<\\/span><\\/p><p><\\/p>\",\"short_description_ar\":\"<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\"><span lang=\\\"ar-eg\\\" style=\\\"font-size:18pt;line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-eg\\\">\\u0639\\u0631\\u0648\\u0636 \\u062a\\u0642\\u0628\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0628\\u0645\\u0627 \\u0644\\u0647\\u0627 \\u0648\\u0639\\u0644\\u064a\\u0647\\u0627 \\u0645\\u0646 \\u0623\\u0635\\u0648\\u0644 \\u0648\\u062e\\u0635\\u0648\\u0645 \\u0628\\u0645\\u0648\\u062c\\u0628 \\u0627\\u0644\\u0625\\u062a\\u0641\\u0627\\u0642 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0637\\u0631\\u0627\\u0641<\\/span><span dir=\\\"ltr\\\" style=\\\"font-size:18pt;line-height:107%;\\\"><\\/span><\\/p><p><\\/p>\",\"button_url\":\"service-request\",\"image\":\"661f728759b9a1713336967.png\"}', NULL, '2024-03-18 15:52:33', '2024-04-28 15:40:41'),
(203, 'service_section.element', '{\"has_image\":[\"1\"],\"title\":\"Project processing\",\"title_ar\":\"\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639\",\"short_description\":\"<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">Providing all solutions for treatment according to the status\\nof each stalled project<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">1. Rehabilitation of the project.<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">2. Refinancing the project.<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">3. Scheduling installments for bad debt.<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">4. Transferring the debt to a new investor.<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">5. Renting the project to an investor who wants to invest\\nwithout transferring ownership.<\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\"><span style=\\\"font-size:16pt;line-height:107%;\\\">6. The defaulter enters into a partnership with a new\\ninvestor.<\\/span><\\/p><p><\\/p>\\n\\n<span style=\\\"font-size:16pt;line-height:107%;font-family:Calibri, sans-serif;\\\">7. Coordination with the Ministry of\\nAgriculture, Water and Environment regarding licenses, such as changing\\nactivity, renewing the license, etc.<\\/span><br \\/>\",\"short_description_ar\":\"<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\" style=\\\"text-align:right;\\\"><span lang=\\\"ar-eg\\\" style=\\\"line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-eg\\\"><font size=\\\"1\\\">\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0643\\u0627\\u0641\\u0629 \\u0627\\u0644\\u062d\\u0644\\u0648\\u0644 \\u0644\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u062d\\u0633\\u0628 \\u062d\\u0627\\u0644\\u0629 \\u0643\\u0644\\n\\u0645\\u0634\\u0631\\u0648\\u0639 \\u0645\\u062a\\u0639\\u062b\\u0631 <\\/font><\\/span><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\" style=\\\"margin-right:0.5in;text-indent:-0.25in;\\\"><font size=\\\"1\\\"><span style=\\\"line-height:107%;\\\">1.<span style=\\\"line-height:normal;font-family:\'Times New Roman\';\\\">\\u00a0\\u00a0 <\\/span><\\/span><span dir=\\\"rtl\\\"><\\/span><span lang=\\\"ar-sa\\\" style=\\\"line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-sa\\\">\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0623\\u0647\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639<\\/span><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\" style=\\\"line-height:107%;\\\"><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\"><\\/span>.<\\/span><\\/font><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\" style=\\\"margin-right:0.5in;text-indent:-0.25in;\\\"><font size=\\\"1\\\"><span style=\\\"line-height:107%;\\\">2.<span style=\\\"line-height:normal;font-family:\'Times New Roman\';\\\">\\u00a0\\u00a0 <\\/span><\\/span><span dir=\\\"rtl\\\"><\\/span><span lang=\\\"ar-sa\\\" style=\\\"line-height:107%;font-family:Arial, sans-serif;\\\" xml:lang=\\\"ar-sa\\\">\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639<\\/span><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\" style=\\\"line-height:107%;\\\"><span dir=\\\"ltr\\\"><\\/span><span dir=\\\"ltr\\\"><\\/span>.<\\/span><\\/font><\\/p><p><\\/p>\\n\\n<p class=\\\"MsoNormal\\\" dir=\\\"rtl\\\" style=\\\"margin-right:0.5in;text-indent:-0.25in;\\\"><font size=\\\"1\\\"><span style=\\\"line-height:107%;\\\">3.<span style=\\\"line-height:normal;font-family:\'Times New Roman\';\\\">\\u00a0\\u00a0 <\\/span><\\/span><span dir=\\\"r