(250, 'foreign_ownership_banner.content', '{\"has_image\":\"1\",\"title\":\"Foreign ownership of real estate\",\"title_ar\":\"\\u0645\\u0644\\u0643\\u064a\\u0629 \\u0627\\u0644\\u0623\\u062c\\u0627\\u0646\\u0628 \\u0644\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a\",\"image\":\"66b499f0b06f41723111920.png\"}', NULL, '2024-08-08 10:15:23', '2024-08-08 14:12:00'),
(251, 'foreign_property_development.content', '{\"has_image\":\"1\",\"title\":\"Property Development\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a\",\"description\":\"Your ideal partner in owning real estate and investing internationally and in the Kingdom of Saudi Arabia? Do you want to obtain a distinguished residency?  We at Property Development help you achieve your goals.\",\"description_ar\":\"\\u0634\\u0631\\u064a\\u0643\\u0643 \\u0627\\u0644\\u0645\\u062b\\u0627\\u0644\\u064a \\u0641\\u064a \\u062a\\u0645\\u0644\\u0643 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u062f\\u0648\\u0644\\u064a\\u0627\\u064b \\u0648\\u0641\\u064a \\u0627\\u0644\\u0645\\u0645\\u0644\\u0643\\u0629 \\u0627\\u0644\\u0639\\u0631\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0633\\u0639\\u0648\\u062f\\u064a\\u0629\\u061f \\u0647\\u0644 \\u062a\\u0631\\u064a\\u062f \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0625\\u0642\\u0627\\u0645\\u0629 \\u0645\\u0645\\u064a\\u0632\\u0629\\u061f \\u0646\\u062d\\u0646 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a \\u0646\\u0633\\u0627\\u0639\\u062f\\u0643 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0642\\u064a\\u0642 \\u0623\\u0647\\u062f\\u0627\\u0641\\u0643.\",\"image\":\"66b49a4542d401723112005.png\",\"image_2\":\"66b49a4583ab41723112005.png\"}', NULL, '2024-08-08 10:16:36', '2024-08-08 14:13:25'),
(252, 'foreign_we_offer_you.content', '{\"header\":\"We offer you\",\"header_ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0642\\u062f\\u0645 \\u0644\\u0643\"}', NULL, '2024-08-08 10:17:13', '2024-08-08 10:17:13'),
(253, 'foreign_we_offer_you.element', '{\"title\":\"Easy real estate ownership\",\"title_ar\":\"\\u0645\\u0644\\u0643\\u064a\\u0629 \\u0639\\u0642\\u0627\\u0631\\u064a\\u0629 \\u0633\\u0647\\u0644\\u0629\",\"description\":\"We help you with all the procedures for purchasing a property, starting from obtaining a license to registering the property.\",\"description_ar\":\"\\u0646\\u0633\\u0627\\u0639\\u062f\\u0643 \\u0641\\u064a \\u0643\\u0627\\u0641\\u0629 \\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0634\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u060c \\u0628\\u062f\\u0621\\u0627\\u064b \\u0645\\u0646 \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0631\\u062e\\u064a\\u0635 \\u0648\\u062d\\u062a\\u0649 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631.\"}', NULL, '2024-08-08 10:18:19', '2024-08-08 10:18:19'),
(254, 'foreign_we_offer_you.element', '{\"title\":\"Various options\",\"title_ar\":\"\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629\",\"description\":\"We offer you a wide range of real estate options, including residential, commercial and industrial properties.\",\"description_ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0642\\u062f\\u0645 \\u0644\\u0643 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 \\u0648\\u0627\\u0633\\u0639\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a\\u0629\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0646\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062c\\u0627\\u0631\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a\\u0629.\"}', NULL, '2024-08-08 10:19:11', '2024-08-08 10:19:11'),
(255, 'foreign_we_offer_you.element', '{\"title\":\"Investing in free zones\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062d\\u0631\\u0629\",\"description\":\"We help you invest in free zones and own real estate in them.\",\"description_ar\":\"\\u0646\\u0633\\u0627\\u0639\\u062f\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062b\\u0645\\u0627\\u0631 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062d\\u0631\\u0629 \\u0648\\u062a\\u0645\\u0644\\u0643 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0641\\u064a\\u0647\\u0627.\"}', NULL, '2024-08-08 10:19:51', '2024-08-08 10:19:51'),
(256, 'foreign_we_offer_you.element', '{\"title\":\"Obtaining distinguished residency\",\"title_ar\":\"\\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0625\\u0642\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0632\\u0629\",\"description\":\"We provide you with the necessary consultations to obtain distinguished residency.\",\"description_ar\":\"\\u0646\\u0642\\u062f\\u0645 \\u0644\\u0643 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0625\\u0642\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0632\\u0629.\"}', NULL, '2024-08-08 10:20:24', '2024-08-08 10:20:24'),
(257, 'foreign_our_services.content', '{\"header\":\"Our services include\",\"header_ar\":\"\\u062e\\u062f\\u0645\\u0627\\u062a\\u0646\\u0627 \\u062a\\u0634\\u0645\\u0644\"}', NULL, '2024-08-08 10:34:50', '2024-08-08 10:34:50'),
(258, 'foreign_our_services.element', '{\"title\":\"Real estate consulting\",\"title_ar\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a\\u0629\",\"description\":\"We provide you with comprehensive consultations about the real estate market.\",\"description_ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0642\\u062f\\u0645 \\u0644\\u0643 \\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0627\\u062a \\u0634\\u0627\\u0645\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0633\\u0648\\u0642 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a.\"}', NULL, '2024-08-08 10:35:43', '2024-08-08 10:35:43'),
(259, 'foreign_our_services.element', '{\"title\":\"Real estate search\",\"title_ar\":\"\\u0627\\u0644\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a\",\"description\":\"We search for properties that suit your requirements and budget.\",\"description_ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0628\\u062d\\u062b \\u0639\\u0646 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u062a\\u0637\\u0644\\u0628\\u0627\\u062a\\u0643 \\u0648\\u0645\\u064a\\u0632\\u0627\\u0646\\u064a\\u062a\\u0643.\"}', NULL, '2024-08-08 10:37:16', '2024-08-08 10:37:16'),
