(261, 'foreign_our_services.element', '{\"title\":\"Real estate financing\",\"title_ar\":\"\\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a\",\"description\":\"We help you obtain the appropriate real estate financing.\",\"description_ar\":\"\\u0646\\u0633\\u0627\\u0639\\u062f\\u0643 \\u0641\\u064a \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0645\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0642\\u0627\\u0631\\u064a \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628.\"}', NULL, '2024-08-08 10:38:26', '2024-08-08 10:38:26'),
