(264, 'foreign_why_choose.element', '{\"title\":\"Specialized Team\",\"title_ar\":\"\\u0641\\u0631\\u064a\\u0642 \\u0645\\u062a\\u062e\\u0635\\u0635\",\"description\":\"We have a specialized team that provides you with support and assistance at all stages of the process.\",\"description_ar\":\"\\u0644\\u062f\\u064a\\u0646\\u0627 \\u0641\\u0631\\u064a\\u0642 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u064a\\u0642\\u062f\\u0645 \\u0644\\u0643 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629.\"}', NULL, '2024-08-08 10:45:07', '2024-08-08 10:45:07'),
